package com.nexusgroup.restaurant.config;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.jobrunr.jobs.mappers.JobMapper;
import org.jobrunr.storage.InMemoryStorageProvider;
import org.jobrunr.storage.StorageProvider;
import org.jobrunr.utils.mapper.jackson.JacksonJsonMapper;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * DO NOT EDIT THIS FILE
 */
@Configuration
public class StorageProviderConfiguration {

    @Bean
    StorageProvider storageProvider(ObjectMapper objectMapper) {
        final var storage = new InMemoryStorageProvider();
        storage.setJobMapper(new JobMapper(new JacksonJsonMapper(objectMapper)));

        return storage;
    }

    @Bean
    ObjectMapper objectMapper() {
        final var objectMapper = new ObjectMapper();
        objectMapper.findAndRegisterModules();

        return objectMapper;
    }
}
